 return {...b,grid:{left:state.narrow?80:100,right:76,top:compare?43:18,bottom:40},legend:{show:compare,top:0,textStyle:{color:C.muted,fontSize:13},itemWidth:10,itemHeight:10},tooltip:{...b.tooltip,trigger:'axis',axisPointer:{type:'shadow'},formatter:ps=>`${ps[0].axisValue}<br>`+ps.map(p=>`${p.marker} ${escape(p.seriesName)} : ${number(p.value)} %`).join('<br>')},xAxis:valueAxis({min:0,max:100,interval:25,axisLabel:{color:C.muted,fontSize:13,formatter:v=>`${v} %`}}),yAxis:categoryAxis(EXP,{inverse:true,axisLabel:{color:C.muted,fontSize:14,formatter:v=>v==='E4'?'E4 · retenu':v},axisLine:{show:false}}),series:stages.map(stage=>({name:stage==='development'?'Développement':'Test 3 HP',type:'bar',barMaxWidth:compare?17:32,barGap:'25%',label:{show:true,position:'right',color:C.ink,fontSize:compare?12:15,formatter:p=>number(p.value)},data:scoreRows(data,stage).map((r,i)=>({value:Number((r.balanced_accuracy*100).toFixed(6)),itemStyle:{color:i===3?C.accent:C.context,opacity:compare&&stage==='development'?.48:1,borderRadius:[0,4,4,0]}}))}))};
